def _parse_value(token, field_type):
    """Parse a single value token for a given field type.
    Returns an int. Raises ValueError on unknown names or invalid tokens.
    """
    token = token.strip()
    if not token:
        raise ValueError("Empty token in cron expression")

    # Try month names (case-insensitive)
    upper = token.upper()
    if field_type == 'month' and upper in MONTH_NAMES:
        return MONTH_NAMES[upper]

    # Try day-of-week names (case-insensitive)
    if field_type == 'dow' and upper in DOW_NAMES:
        return DOW_NAMES[upper]

    # Try numeric
    try:
        return int(token)
    except ValueError:
        raise ValueError(f"Unknown value '{token}' for field type {field_type}")


def _parse_field(field_str, field_type, min_val, max_val):
    """Parse a single cron field and return a set of matching integers.

    field_type is one of: 'minute', 'hour', 'dom', 'month', 'dow'
    """
    # Determine if this field is exactly '*' (for Vixie day logic)
    stripped = field_str.strip()
    is_star = (stripped == '*')

    values = set()

    for item in stripped.split(','):
        item = item.strip()
        if not item:
            raise ValueError("Empty item in comma-separated list")

        # Check for step
        step = 1
        if '/' in item:
            parts = item.split('/')
            if len(parts) != 2:
                raise ValueError(f"Invalid step syntax in '{item}'")
            base_str, step_str = parts[0], parts[1].strip()
            try:
                step = int(step_str)
            except ValueError:
                raise ValueError(f"Invalid step value '{step_str}'")
            if step <= 0:
                raise ValueError("Step must be positive")
            item = base_str

        # Now parse the base part
        if item == '*':
            start = min_val
            end = max_val
        elif '-' in item:
            parts = item.split('-')
            if len(parts) != 2:
                raise ValueError(f"Invalid range syntax in '{item}'")
            a_str, b_str = parts[0].strip(), parts[1].strip()
            a = _parse_value(a_str, field_type)
            b = _parse_value(b_str, field_type)

            # For dow, 7 is equivalent to 0 (Sunday)
            if field_type == 'dow':
