def merge(base: dict, *overrides: dict) -> dict:
    """
    Deep merge for configuration layers (later wins).

    - Dicts are merged recursively. Any other value in an override replaces the base value.
    - A key whose override value is None deletes that key from the result.
    - A key ending in '+' appends to a list: {"plugins+": ["x"]} appends items to base "plugins".
      If base value exists and is not a list, raise TypeError. The '+' key never appears in result.
    - Inputs are not mutated; result is a deep copy with no shared mutable objects.
    """

    def _deep_copy(value):
        if isinstance(value, dict):
            return {k: _deep_copy(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_deep_copy(item) for item in value]
        else:
            return value

    def _merge_into(result: dict, override: dict) -> None:
        """Merge override into result in-place (result is already a deep copy)."""
        for key, value in override.items():
            if key.endswith('+'):
                base_key = key[:-1]
                items = value
                # Items should be iterable; we'll append each item.
                # If items is None, treat as empty? The spec says "appends the items to the base list".
                # Let's assume items is a list or iterable.
                if items is None:
                    items = []

                if base_key in result:
                    existing = result[base_key]
                    if not isinstance(existing, list):
                        raise TypeError(f"Cannot append to non-list value for key '{base_key}'")
                    # Append deep copies of items
                    for item in items:
                        existing.append(_deep_copy(item))
                else:
                    # Create new list with deep copies of items
                    result[base_key] = [_deep_copy(item) for item in items]
            elif value is None:
                # Delete the key from result if present
                if key in result:
                    del result[key]
            else:
                if key in result and isinstance(result[key], dict) and isinstance(value, dict):
                    # Recursive merge
                    _merge_into(result[key], value)
                else:
                    # Replace with deep copy of the new value
                    result[key] = _deep_copy(value)

    # Start with a deep copy of base
    result = _deep_copy(base)

    # Merge each override in order (later wins)
    for override in overrides:
        _merge_into(result, override)

    return result
