def flatten(obj, sep="."):
    """
    Flatten a nested dict/list structure into a flat dict with path keys.

    - Dict keys are joined with sep
    - List items use their index (e.g., "a.0.b")
    - Empty dicts and empty lists are kept as leaf values
    - Any other value is a leaf
    - Top-level must be a dict, else TypeError
    - Keys must be strings that don't contain sep, else ValueError
    - Order: depth-first, in the input's order
    """
    if not isinstance(obj, dict):
        raise TypeError("Top-level object must be a dict")

    result = {}

    def _flatten(prefix, value):
        # Check if this is a leaf (empty dict, empty list, or non-container)
        if isinstance(value, dict):
            if len(value) == 0:
                # Empty dict is a leaf
                result[prefix] = value
                return
            # Non-empty dict: recurse
            for key in value:
                if not isinstance(key, str):
                    raise ValueError(f"Key must be a string, got {type(key).__name__}")
                if sep in key:
                    raise ValueError(f"Key '{key}' contains separator '{sep}'")
                new_prefix = f"{prefix}{sep}{key}" if prefix else key
                _flatten(new_prefix, value[key])
        elif isinstance(value, list):
            if len(value) == 0:
                # Empty list is a leaf
                result[prefix] = value
                return
            # Non-empty list: recurse over indices
            for i, item in enumerate(value):
                new_prefix = f"{prefix}{sep}{i}" if prefix else str(i)
                _flatten(new_prefix, item)
        else:
            # Leaf value (number, string, bool, None, etc.)
            result[prefix] = value

    _flatten("", obj)
    return result


def unflatten(flat, sep="."):
    """
    Unflatten a flat dict with path keys back into nested dicts/lists.

    - A path segment that is a non-negative integer without leading zeros creates a list
    - Lists must be dense: indices must be exactly 0..n-1 (in any input order)
    - Conflicts raise ValueError
    """
    if not isinstance(flat, dict):
        raise TypeError("Input must be a dict")

    # Build the nested structure
    result = {}

    def _is_valid_index(segment):
        """Check if segment is a valid non-negative integer without leading zeros."""
        if not isinstance(segment, str):
            return False
        if len(segment) == 0:
            return False
        # Must be all digits
        if not segment.isdigit():
            return False
        # No leading zeros (except for "0" itself)
        if len(segment) > 1 and segment[0] == '0':
            return False
        return True

    def _get_or_create(path_parts, value):
        """
        Insert value at the given path in result.
        path_parts is a list of strings representing each segment.
        Returns the node where value should be placed (for conflict checking).
        """
        if len(path_parts) == 0:
            return result

        current = result
        for i, part in enumerate(path_parts):
            # Check if we can create/extend a list at this level
            is_last = (i == len(path_parts) - 1)

            if _is_valid_index(part):
                idx = int(part)
                # current must be a list or we need to create one
                if not isinstance(current, list):
                    # If current is a dict, that's a conflict
                    if isinstance(current, dict):
                        raise ValueError(f"Conflict: cannot create list at path for index {idx}")
                    # Create a new list
                    current = []

                # Ensure the list is long enough
                while len(current) <= idx:
