            if e <= start or s >= end:
                out.append((s, e))
            else:
                if s < start:
                    out.append((s, start))
                if e > end:
                    out.append((end, e))
        self._iv = out

    def contains(self, x):
        # Find the interval whose start is <= x
        i = bisect.bisect_right(self._iv, (x, float('inf'))) - 1
        if i >= 0:
            s, e = self._iv[i]
            if s <= x < e:
                return True
        return False

    def free(self, lo, hi):
        if lo >= hi:
            return []
        gaps = []
        cur = lo
        for s, e in self._iv:
            if e <= cur:
                continue
            if s > cur:
                gaps.append((cur, min(s, hi)))
                cur = s
            if e >= hi:
                break
            cur = max(cur, e)
        if cur < hi:
            gaps.append((cur, hi))
        return gaps

    def __iter__(self):
        return iter(self._iv)

    def __len__(self):
        return len(self._iv)
