from collections import deque
import heapq
import string

def route(grid: list[str]) -> tuple[int, str] | None:
    # Validate grid
    if not grid:
        raise ValueError("Empty grid")

    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Check for ragged rows
    for i, row in enumerate(grid):
        if len(row) != cols:
            raise ValueError(f"Ragged rows: row {i} has length {len(row)} but expected {cols}")

    # Find S and E, count letters, validate characters
    start = None
    end = None
    letter_count = {}

    for r in range(rows):
        for c in range(cols):
            ch = grid[r][c]
            if ch == 'S':
                if start is not None:
                    raise ValueError("More than one S")
                start = (r, c)
            elif ch == 'E':
                if end is not None:
                    raise ValueError("More than one E")
                end = (r, c)
            elif ch in string.ascii_lowercase:
                letter_count[ch] = letter_count.get(ch, 0) + 1
            elif ch not in "SE#." and ch not in "123456789":
                raise ValueError(f"Unknown character: {ch}")

    if start is None:
        raise ValueError("No S found")
    if end is None:
        raise ValueError("No E found")

    # Check letter counts: each must be 0 or 2
    for ch, count in letter_count.items():
        if count != 2:
            raise ValueError(f"Letter '{ch}' appears {count} times (must be 0 or 2)")

    # Build teleport map: for each letter, store the two positions
    teleport = {}
    for r in range(rows):
        for c in range(cols):
            ch = grid[r][c]
            if ch in string.ascii_lowercase:
                if ch not in teleport:
                    teleport[ch] = []
                teleport[ch].append((r, c))

    # Cost function for entering a cell
    def cell_cost(r: int, c: int) -> int:
        ch = grid[r][c]
        if ch == 'S' or ch == 'E':
            return 1
        elif ch == '.':
            return 1
        elif '1' <= ch <= '9':
            return int(ch)
        elif ch in string.ascii_lowercase:
            return 1
        else:
            # Should not reach here due to validation
            return 1

    # Check if a cell is walkable (not a wall)
    def is_walkable(r: int, c: int) -> bool:
        if r < 0 or r >= rows or c < 0 or c >= cols:
            return False
        return grid[r][c] != '#'

    # Initialize
    INF = float('inf')
    best_cost = [[INF] * cols for _ in range(rows)]
    best_moves = [['' for _ in range(cols)] for _ in range(rows)]

    start_r, start_c = start
    best_cost[start_r][start_c] = 0
    best_moves[start_r][start_c] = ""

    # Priority queue: (cost, moves, r, c)
    pq = []
    heapq.heappush(pq, (0, "", start_r, start_c))

    while pq:
        cost, moves, r, c = heapq.heappop(pq)

        # If this state is not the best for (r,c), skip
        if cost > best_cost[r][c]:
            continue
        if cost == best_cost[r][c] and moves > best_moves[r][c]:
            continue

        # If we reached E, return since Dijkstra guarantees first pop of E 
        # is the one with minimum cost and lex-smallest moves.
        if (r, c) == end:
            return (cost, moves)

        # Try all moves in order: D, L, R, T, U

        # D: down
        nr, nc = r + 1, c
        if is_walkable(nr, nc):
            new_cost = cost + cell_cost(nr, nc)
            new_moves = moves + "D"
            if new_cost < best_cost[nr][nc] or (new_cost == best_cost[nr][nc] and new_moves < best_moves[nr][nc]):
                best_cost[nr][nc] = new_cost
                best_moves[nr][nc] = new_moves
                heapq.heappush(pq, (new_cost, new_moves, nr, nc))

        # L: left
        nr, nc = r, c - 1
        if is_walkable(nr, nc):
            new_cost = cost + cell_cost(nr, nc)
            new_moves = moves + "L"
            if new_cost < best_cost[nr][nc] or (new_cost == best_cost[nr][nc] and new_moves < best_moves[nr][nc]):
                best_cost[nr][nc] = new_cost
                best_moves[nr][nc] = new_moves
                heapq.heappush(pq, (new_cost, new_moves, nr, nc))

        # R: right
        nr, nc = r, c + 1
        if is_walkable(nr, nc):
            new_cost = cost + cell_cost(nr, nc)
            new_moves = moves + "R"
            if new_cost < best_cost[nr][nc] or (new_cost == best_cost[nr][nc] and new_moves < best_moves[nr][nc]):
                best_cost[nr][nc] = new_cost
                best_moves[nr][nc] = new_moves
                heapq.heappush(pq, (new_cost, new_moves, nr, nc))

        # T: teleport (only if current cell is a pad)
        ch = grid[r][c]
        if ch in string.ascii_lowercase and ch in teleport:
            pads = teleport[ch]
            for pr, pc in pads:
                if (pr, pc) != (r, c):
                    new_cost = cost + 2  # Teleport costs 2
                    new_moves = moves + "T"
                    if new_cost < best_cost[pr][pc] or (new_cost == best_cost[pr][pc] and new_moves < best_moves[pr][pc]):
                        best_cost[pr][pc] = new_cost
                        best_moves[pr][pc] = new_moves
                        heapq.heappush(pq, (new_cost, new_moves, pr, pc))

        # U: up
        nr, nc = r - 1, c
        if is_walkable(nr, nc):
            new_cost = cost + cell_cost(nr, nc)
            new_moves = moves + "U"
            if new_cost < best_cost[nr][nc] or (new_cost == best_cost[nr][nc] and new_moves < best_moves[nr][nc]):
                best_cost[nr][nc] = new_cost
                best_moves[nr][nc] = new_moves
                heapq.heappush(pq, (new_cost, new_moves, nr, nc))

    # If we exhausted the queue without reaching E
    return None
