import re
from typing import List, Optional, Tuple


class Version:
    def __init__(self, major: int, minor: int, patch: int, prerelease: Optional[List[str]] = None, build: Optional[List[str]] = None):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease if prerelease is not None else []
        self.build = build if build is not None else []

    def _cmp(self, other: 'Version') -> int:
        # Compare major, minor, patch
        for a, b in [(self.major, other.major), (self.minor, other.minor), (self.patch, other.patch)]:
            if a < b:
                return -1
            elif a > b:
                return 1

        # Both have same major.minor.patch
        # Prerelease comparison
        has_self_pre = len(self.prerelease) > 0
        has_other_pre = len(other.prerelease) > 0

        if has_self_pre and not has_other_pre:
            return -1
        elif not has_self_pre and has_other_pre:
            return 1
        elif has_self_pre and has_other_pre:
            # Compare prerelease identifiers
            self_ids = self.prerelease
            other_ids = other.prerelease
            for i in range(min(len(self_ids), len(other_ids))):
                s_id = self_ids[i]
                o_id = other_ids[i]
                s_num = s_id.isdigit()
                o_num = o_id.isdigit()

                if s_num and o_num:
                    s_val = int(s_id)
                    o_val = int(o_id)
                    if s_val < o_val:
                        return -1
                    elif s_val > o_val:
                        return 1
                elif s_num and not o_num:
                    # numeric < alphanumeric
                    return -1
                elif not s_num and o_num:
                    # alphanumeric > numeric
                    return 1
                else:
                    # Both alphanumeric, compare in ASCII order
                    if s_id < o_id:
                        return -1
                    elif s_id > o_id:
                        return 1

            # All compared identifiers are equal; shorter list is smaller
            if len(self_ids) < len(other_ids):
                return -1
            elif len(self_ids) > len(other_ids):
                return 1
            else:
                return 0
        else:
            # Neither has prerelease
            return 0

    def __eq__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp(other) == 0

    def __lt__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp(other) < 0

    def __le__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp(other) <= 0

    def __gt__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp(other) > 0

    def __ge__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp(other) >= 0

    def __hash__(self) -> int:
        # Hash based on major, minor, patch, and prerelease (build ignored for equality)
        return hash((self.major, self.minor, self.patch, tuple(self.prerelease)))

    def __repr__(self) -> str:
        s = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            s += "-" + ".".join(self.prerelease)
        if self.build:
            s += "+" + ".".join(self.build)
        return s


def _validate_numeric_part(s: str, name: str) -> int:
    """Validate a numeric part (no leading zeros unless it's '0')."""
    if not s:
        raise ValueError(f"Empty {name}")
    if not re.fullmatch(r'[0-9]+', s):
        raise ValueError(f"Invalid {name}: {s}")
    if len(s) > 1 and s[0] == '0':
        raise ValueError(f"Leading zero in {name}: {s}")
    return int(s)


def _validate_identifier(s: str, name: str) -> str:
    """Validate a prerelease/build identifier."""
    if not s:
        raise ValueError(f"Empty {name} identifier")
    if not re.fullmatch(r'[0-9A-Za-z-]+', s):
        raise ValueError(f"Invalid {name} identifier: {s}")
    # Numeric identifiers cannot have leading zeros
    if s.isdigit() and len(s) > 1 and s[0] == '0':
        raise ValueError(f"Leading zero in numeric {name} identifier: {s}")
    return s


def parse(v: str) -> Version:
    """Parse a SemVer 2.0.0 version string."""
    if not isinstance(v, str):
        raise ValueError("Version must be a string")

    s = v.strip()
    if not s:
        raise ValueError("Empty version string")

    # Strip leading 'v' or '='
    if s[0] in ('v', '='):
        s = s[1:]

    if not s:
        raise ValueError("Empty version after prefix")

    # Split off build metadata
    build_str = None
    if '+' in s:
        idx = s.index('+')
        build_str = s[idx + 1:]
        s = s[:idx]

    # Split off prerelease
    prerelease_str = None
    if '-' in s:
        # Find the last '-' that could be a prerelease separator
        # But we need to be careful: the version part is MAJOR.MINOR.PATCH, then optional -PRERELEASE
        # So split at the first '-' after the patch
        # Actually, let's find where the numeric part ends
        # The format is: MAJOR.MINOR.PATCH[-PRERELEASE]
        # So we need to find the boundary between PATCH and PRERELEASE

        # Let's try to match the full pattern
        pass

    # Use a regex to parse the core version
    # Pattern: ^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z-.]+))?$
    # But we need to validate no leading zeros in numeric parts

    m = re.fullmatch(r'(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?', s)
    if not m:
        raise ValueError(f"Invalid version format: {v}")

    major_str, minor_str, patch_str, prerelease_part = m.groups()

    major = _validate_numeric_part(major_str, "MAJOR")
    minor = _validate_numeric_part(minor_str, "MINOR")
    patch = _validate_numeric_part(patch_str, "PATCH")

    prerelease = []
    if prerelease_part is not None:
        # Split by '.' and validate each identifier
        ids = prerelease_part.split('.')
        for ident in ids:
            _validate_identifier(ident, "prerelease")
            prerelease.append(ident)

    build = []
    if build_str is not None:
        if not build_str:
            raise ValueError("Empty build metadata")
        ids = build_str.split('.')
        for ident in ids:
            _validate_identifier(ident, "build")
            build.append(ident)

    return Version(major, minor, patch, prerelease, build)


def _parse_partial_version(s: str) -> Tuple[Optional[int], Optional[int], Optional[int]]:
    """Parse a partial version like '1', '1.2', '1.2.3', 'X', '1.x', etc.
    Returns (major, minor, patch) where None means wildcard/X."""
    if not s:
        raise ValueError("Empty version in comparator")

    # Strip leading v or =
    if s[0] in ('v', '='):
        s = s[1:]

    if not s:
        raise ValueError("Empty version after prefix in comparator")

    # Check for X/x wildcard
    parts = s.split('.')
    result = []
    for i, part in enumerate(parts):
        if i > 2:
            raise ValueError(f"Too many version parts in partial version: {s}")
        if part in ('X', 'x', '*'):
            result.append(None)
        elif re.fullmatch(r'\d+', part):
            # Validate no leading zeros
            if len(part) > 1 and part[0] == '0':
                raise ValueError(f"Leading zero in version part: {part}")
            result.append(int(part))
        else:
            raise ValueError(f"Invalid version part '{part}' in partial version: {s}")

    # Pad with Nones up to 3 parts
    while len(result) < 3:
        result.append(None)

    return tuple(result)


def _expand_comparator(op: str, major: Optional[int], minor: Optional[int], patch: Optional[int]) -> List[Tuple[str, Version]]:
    """Expand a single comparator into one or more (op, version) pairs.

    For X-ranges and partial versions with operators, we need special handling.
    Returns a list of (operator_string, Version) tuples that must all be satisfied.
    """
    # If all parts are specified, it's straightforward
    if major is not None and minor is not None and patch is not None:
        v = Version(major, minor, patch)
        return [(op, v)]

    # Partial version handling
    # The rules from the spec:
    # 1.2.x means >=1.2.0 <1.3.0
    # 1 means >=1.0.0 <2.0.0
    # With operators:
    #   >1.2 means >=1.3.0
    #   <=1.2 means <1.3.0
    #   <1.2 means <1.2.0
    #   >=1.2 means >=1.2.0

    if major is None:
        # X or * - matches anything
        return []  # No constraints

    if minor is None:
        # Like "1" or "1.x"
        # Means >=1.0.0 <2.0.0 for no operator
        # For operators:
        #   >1 means >=2.0.0 (since all 1.x are less than 2)
        #   <=1 means <2.0.0
        #   <1 means <1.0.0
        #   >=1 means >=1.0.0

        if op == '':
            return [('>=', Version(major, 0, 0)), ('<', Version(major + 1, 0, 0))]
        elif op == '>':
            return [('>=', Version(major + 1, 0, 0))]
        elif op == '<=':
            return [('<', Version(major + 1, 0, 0))]
        elif op == '<':
            return [('<', Version(major, 0, 0))]
        elif op == '>=':
            return [('>=', Version(major, 0, 0))]
        elif op == '=':
            return [('>=', Version(major, 0, 0)), ('<', Version(major + 1, 0, 0))]
        else:
            raise ValueError(f"Unknown operator: {op}")

    # minor is not None, patch may be None
    # Like "1.2" or "1.2.x"
    if patch is None:
        # Means >=1.2.0 <1.3.0 for no operator
        # For operators:
        #   >1.2 means >=1.3.0
        #   <=1.2 means <1.3.0
        #   <1.2 means <1.2.0
        #   >=1.2 means >=1.2.0

        if op == '':
            return [('>=', Version(major, minor, 0)), ('<', Version(major, minor + 1, 0))]
        elif op == '>':
            return [('>=', Version(major, minor + 1, 0))]
        elif op == '<=':
            return [('<', Version(major, minor + 1, 0))]
        elif op == '<':
            return [('<', Version(major, minor, 0))]
        elif op == '>=':
            return [('>=', Version(major, minor, 0))]
        elif op == '=':
            return [('>=', Version(major, minor, 0)), ('<', Version(major, minor + 1, 0))]
        else:
            raise ValueError(f"Unknown operator: {op}")

    # Should not reach here since we handled all None cases above
    raise ValueError("Unexpected state in _expand_comparator")


def _parse_comparator_set(set_str: str) -> List[List[Tuple[str, Version]]]:
    """Parse a single comparator set (whitespace-separated comparators).
    Returns a list of expanded comparators, each being a list of (op, version) pairs.
    Actually, let's return a flat list of (op, version) pairs that must all be satisfied.
    But for hyphen ranges, we need to handle them specially.

    Let me restructure: parse_comparator_set returns a list of (op, Version) tuples.
    """
    set_str = set_str.strip()
    if not set_str or set_str == '*':
        return []  # Matches anything

    # Check for hyphen range: "X.Y.Z - A.B.C"
    # The hyphen range has the form: partial_version '-' partial_version
    # We need to detect this pattern. It's tricky because '-' can appear in prerelease versions too.
    # But hyphen ranges don't have prereleases in the bounds typically.

    # Let's try to match the hyphen pattern
    # Pattern: (partial_version) - (partial_version)
    # The partial versions don't contain spaces, and the hyphen is surrounded by spaces.

    hyphen_match = re.fullmatch(r'(\S+)\s+-\s+(\S+)', set_str)
    if hyphen_match:
        lower_str = hyphen_match.group(1)
        upper_str = hyphen_match.group(2)

        # Parse lower and upper partial versions
        lower_parts = _parse_partial_version(lower_str)
        upper_parts = _parse_partial_version(upper_str)

        # Lower bound is inclusive (>=), upper bound depends on whether it's partial
        # Fill zeros for lower bound
        l_major, l_minor, l_patch = lower_parts
        if l_major is None:
            l_major = 0
        if l_minor is None:
            l_minor = 0
        if l_patch is None:
            l_patch = 0

        u_major, u_minor, u_patch = upper_parts

        comparators = []
        # Lower bound: >= lower_version
        comparators.append(('>=', Version(l_major, l_minor, l_patch)))

        # Upper bound: if all three parts specified, <= ; otherwise < next version
        if u_major is not None and u_minor is not None and u_patch is not None:
            comparators.append(('<=', Version(u_major, u_minor, u_patch)))
        elif u_major is not None and u_minor is not None:
            # u_patch is None, so < (u_major, u_minor+1, 0)
            comparators.append(('<', Version(u_major, u_minor + 1, 0)))
        elif u_major is not None:
            # u_minor and u_patch are None, so < (u_major+1, 0, 0)
            comparators.append(('<', Version(u_major + 1, 0, 0)))
        else:
            # All wildcards, no upper bound constraint
            pass

        return comparators

    # Normal comparator set: whitespace-separated comparators
    # Each comparator is like ">1.2.3", "<=1.2", "1.2.x", "~1.2.3", "^1.2.3", etc.

    # Tokenize the set into individual comparators
    # We need to handle tilde (~) and caret (^) prefixes
    tokens = set_str.split()
    if not tokens:
        return []

    comparators = []
    for token in tokens:
        if not token:
            continue

        # Check for tilde or caret
        if token.startswith('~'):
            version_part = token[1:]
            parts = _parse_partial_version(version_part)
            major, minor, patch = parts

            if major is None:
                # ~X - matches anything? Let's treat as no constraint
                continue

            if minor is None:
                # ~1 means >=1.0.0 <2.0.0
                comparators.append(('>=', Version(major, 0, 0)))
                comparators.append(('<', Version(major + 1, 0, 0)))
            elif patch is None:
                # ~1.2 means >=1.2.0 <1.3.0
                comparators.append(('>=', Version(major, minor, 0)))
                comparators.append(('<', Version(major, minor + 1, 0)))
            else:
                # ~1.2.3 means >=1.2.3 <1.3.0
                comparators.append(('>=', Version(major, minor, patch)))
                comparators.append(('<', Version(major, minor + 1, 0)))

        elif token.startswith('^'):
            version_part = token[1:]
            parts = _parse_partial_version(version_part)
            major, minor, patch = parts

            if major is None:
                # ^X - matches anything? Treat as no constraint
                continue

            if minor is None:
                # ^1 means >=1.0.0 <2.0.0
                comparators.append(('>=', Version(major, 0, 0)))
                comparators.append(('<', Version(major + 1, 0, 0)))
            elif patch is None:
                # ^1.2.x means >=1.2.0 <2.0.0
                # ^0.2.x means >=0.2.0 <0.3.0 (since major is 0)
                # Wait, the spec says:
                #   ^1.2.x is >=1.2.0 <2.0.0
                #   ^0.0.x is >=0.0.0 <0.1.0
                #   ^0.x is >=0.0.0 <1.0.0

                if major == 0:
                    # ^0.x means >=0.0.0 <1.0.0
                    comparators.append(('>=', Version(0, 0, 0)))
                    comparators.append(('<', Version(1, 0, 0)))
                else:
                    # ^1.2.x means >=1.2.0 <2.0.0
                    comparators.append(('>=', Version(major, minor, 0)))
                    comparators.append(('<', Version(major + 1, 0, 0)))
            else:
                # Full version specified
                if major > 0:
                    # ^1.2.3 means >=1.2.3 <2.0.0
                    comparators.append(('>=', Version(major, minor, patch)))
                    comparators.append(('<', Version(major + 1, 0, 0)))
                elif minor > 0:
                    # ^0.2.3 means >=0.2.3 <0.3.0
                    comparators.append(('>=', Version(0, minor, patch)))
                    comparators.append(('<', Version(0, minor + 1, 0)))
                else:
                    # ^0.0.3 means >=0.0.3 <0.0.4
                    comparators.append(('>=', Version(0, 0, patch)))
                    comparators.append(('<', Version(0, 0, patch + 1)))

        else:
            # Regular comparator with optional operator
            # Check for operators
            op = ''
            version_str = token

            if token.startswith('>='):
                op = '>='
                version_str = token[2:]
            elif token.startswith('<='):
                op = '<='
                version_str = token[2:]
            elif token.startswith('>'):
                op = '>'
                version_str = token[1:]
            elif token.startswith('<'):
                op = '<'
                version_str = token[1:]
            elif token.startswith('='):
                op = '='
                version_str = token[1:]

            # Now parse the version part (which may be partial)
            parts = _parse_partial_version(version_str)
            major, minor, patch = parts

            expanded = _expand_comparator(op, major, minor, patch)
            comparators.extend(expanded)

    return comparators


def _version_satisfies_comparators(v: Version, comparators: List[Tuple[str, Version]]) -> bool:
    """Check if a version satisfies all comparators in the list."""
    for op, cmp_ver in comparators:
        if op == '>=':
            if not (v >= cmp_ver):
                return False
        elif op == '<=':
            if not (v <= cmp_ver):
                return False
        elif op == '>':
            if not (v > cmp_ver):
                return False
        elif op == '<':
