    # Prerelease rule: a version with a prerelease only satisfies a set if some
    # comparator in that set has a version with the same MAJOR.MINOR.PATCH and a prerelease
    if len(v.prerelease) > 0:
        # Check if any comparator has same MMP and a prerelease
        found = False
        for _, cmp_ver in comparators:
            if _same_mmp(v, cmp_ver) and len(cmp_ver.prerelease) > 0:
                found = True
                break
