from __future__ import annotations

import dataclasses
import typing
from typing import Any, get_type_hints


class LoadError(ValueError):
    def __init__(self, path: str, message: str) -> None:
        self.path = path
        super().__init__(f"{path}: {message}")


def _load_value(data: Any, tp: Any, path: str) -> Any:
    """Load a value from data according to type annotation tp."""
    # Handle Optional[T] / T | None
    origin = typing.get_origin(tp)
    args = typing.get_args(tp)

    # Check for Optional pattern (T | None or Optional[T])
    if origin is typing.Union:
        if len(args) == 2 and (args[0] is type(None) or args[1] is type(None)):
            # Optional[T]
            if data is None:
                return None
            inner = args[1] if args[0] is type(None) else args[0]
            return _load_value(data, inner, path)

    # Handle general Union (int | str, etc.)
    if origin is typing.Union:
        errors = []
        for member in args:
            try:
                return _load_value(data, member, path)
            except LoadError as e:
                errors.append(e)
        # If none loaded, raise with the union's own path
        raise LoadError(path, f"could not load value {data!r} as {tp}")

    # Handle Literal
    if origin is typing.Literal or tp.__class__.__name__ == 'Literal':
        # Get literal values
        lit_args = typing.get_args(tp)
        for val in lit_args:
            if data == val and type(data) == type(val):
                return data
        raise LoadError(path, f"expected one of {lit_args}, got {data!r}")

    # Handle nested dataclass
    if isinstance(tp, type) and dataclasses.is_dataclass(tp):
        if not isinstance(data, dict):
            raise LoadError(path, f"expected dict for dataclass {tp.__name__}, got {type(data).__name__}")
        return _load_dataclass(tp, data, path)

    # Handle list[T]
    if origin is list:
        if not isinstance(data, list):
            raise LoadError(path, f"expected list, got {type(data).__name__}")
        inner_tp = args[0] if args else Any
        result = []
        for i, item in enumerate(data):
            item_path = f"{path}[{i}]"
            result.append(_load_value(item, inner_tp, item_path))
        return result

    # Handle dict[str, T]
    if origin is dict:
        if not isinstance(data, dict):
            raise LoadError(path, f"expected dict, got {type(data).__name__}")
        key_tp = args[0] if len(args) > 0 else Any
        val_tp = args[1] if len(args) > 1 else Any
        result = {}
        for k, v in data.items():
            # Validate key type
            loaded_key = _load_value(k, key_tp, f"{path}.{k}")
            key_path = f"{path}.{loaded_key}"
            loaded_val = _load_value(v, val_tp, key_path)
            result[loaded_key] = loaded_val
        return result

    # Handle tuple[T, ...] (variable length)
    if origin is tuple:
        if not isinstance(data, list):
            raise LoadError(path, f"expected list for tuple, got {type(data).__name__}")
        if len(args) == 2 and args[1] is Ellipsis:
            # Variable length tuple[T, ...]
            inner_tp = args[0]
            result = []
            for i, item in enumerate(data):
                item_path = f"{path}[{i}]"
                result.append(_load_value(item, inner_tp, item_path))
            return tuple(result)
        else:
            # Fixed length tuple[A, B, C]
            if len(data) != len(args):
                raise LoadError(path, f"expected tuple of length {len(args)}, got list of length {len(data)}")
            result = []
            for i, (item, member_tp) in enumerate(zip(data, args)):
                item_path = f"{path}[{i}]"
                result.append(_load_value(item, member_tp, item_path))
            return tuple(result)

    # Handle basic types
    if tp is int:
        if isinstance(data, bool):
            raise LoadError(path, f"expected int, got bool")
        if isinstance(data, int):
            return data
        raise LoadError(path, f"expected int, got {type(data).__name__}")

    if tp is float:
        if isinstance(data, bool):
            raise LoadError(path, f"expected float, got bool")
        if isinstance(data, int):
            return float(data)
        if isinstance(data, float):
            return data
        raise LoadError(path, f"expected float, got {type(data).__name__}")

    if tp is str:
        if isinstance(data, str):
            return data
        raise LoadError(path, f"expected str, got {type(data).__name__}")

    if tp is bool:
        if isinstance(data, bool):
            return data
        raise LoadError(path, f"expected bool, got {type(data).__name__}")

    if tp is type(None):
        if data is None:
            return None
        raise LoadError(path, f"expected None, got {type(data).__name__}")

    # If tp is Any or unknown type, just return data
    if tp is Any:
        return data

    raise LoadError(path, f"unsupported type annotation {tp}")


def _load_dataclass(cls: type, data: dict, path: str) -> Any:
    """Load a dataclass instance from a dict."""
    hints = get_type_hints(cls)
    fields = dataclasses.fields(cls)

    # Check for unknown keys
    field_names = {f.name for f in fields}
    for key in data.keys():
