    if _is_union(tp):
        args = _get_union_args(tp)

        # Check for Optional pattern (T | None or Optional[T])
        none_idx = None
        non_none_args = []
        for i, arg in enumerate(args):
            if arg is type(None):
                none_idx = i
            else:
                non_none_args.append(arg)

        if none_idx is not None and len(non_none_args) == 1:
            # Optional[T]
            if data is None:
                return None
            inner = non_none_args[0]
            return _load_value(data, inner, path)

        # General Union (int | str, etc.) - try members left to right
        for member in args:
            if member is type(None):
                continue
            try:
                return _load_value(data, member, path)
            except LoadError:
                continue
        # If none loaded (or only None was an option and data isn't None)
